import { sign } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";

import type { E2eUser } from "./e2e-users";

/** The backend's test issuer (app/config.py): fixed there, never configurable. */
export const TEST_ISSUER = "http://localhost/test-issuer/v2.0";
export const TEST_AUDIENCE = "api://adops360-test-issuer";
const TEST_TENANT = "e2e-test-tenant";
/** Long enough for any run; the backend checks it, and the frontend reads it as expires_at. */
const TOKEN_LIFETIME_SECONDS = 4 * 3600;

/** The test issuer's private key, generated by scripts/generate_test_issuer_keys.sh; never printed. */
export function readPrivateKey(path: string): string {
  if (!existsSync(path)) {
    throw new Error(`The test issuer private key is missing at ${path}. Run scripts/generate_test_issuer_keys.sh.`);
  }
  return readFileSync(path, "utf8");
}

const base64url = (value: object): string => Buffer.from(JSON.stringify(value)).toString("base64url");

/** An Entra-shaped version 2 access token of the test issuer for `user`, signed RS256 with `privateKeyPem`. */
export function signTestIssuerToken(user: E2eUser, privateKeyPem: string, nowSeconds: number = Math.floor(Date.now() / 1000)): string {
  const header = base64url({ alg: "RS256", typ: "JWT" });
  const payload = base64url({
    iss: TEST_ISSUER,
    aud: TEST_AUDIENCE,
    iat: nowSeconds,
    exp: nowSeconds + TOKEN_LIFETIME_SECONDS,
    ver: "2.0",
    scp: "access_as_user",
    oid: user.oid,
    tid: TEST_TENANT,
    email: user.email,
  });
  const signature = sign("sha256", Buffer.from(`${header}.${payload}`), privateKeyPem).toString("base64url");
  return `${header}.${payload}.${signature}`;
}
